INSERT INTO "ec_home" ("id","slug","status","author_id","primary_byline_id","created_at","updated_at","published_at","scheduled_at","deleted_at","version","live_revision_id","draft_revision_id","locale","translation_group","title","hero_image","stat_1","stat_2","stat_3","stat_4","intro_heading","intro","cta_label","cta_url","services_heading","services_intro") VALUES ('01KZVCABN5VQDYZWW45HQ7Q1FH','home','published',NULL,NULL,'2026-08-12T16:19:05.509Z','2026-08-12T16:51:59.589Z','2026-08-12T16:19:05.509Z',NULL,NULL,2,NULL,NULL,'vi','01KZVCABN5VQDYZWW45HQ7Q1FH','Trang chủ','{"provider": "local", "id": "01KZVE8Q67PC9JQFAQ67WRCPPQ", "alt": "Hệ thống bếp công nghiệp AVC thi công", "width": 1319, "height": 824, "mimeType": "image/jpeg", "filename": "hero-avc.jpg", "meta": {"storageKey": "01KZVE8Q67PC9JQFAQ67WRCPPQ.jpg"}}','15+ Năm Kinh Nghiệm','1.500+ Công Trình Đã Triển Khai','Dự Án Trên Toàn Quốc','Hỗ Trợ & Bảo Trì 24/7','CÔNG TY TNHH THIẾT BỊ CÔNG NGHIỆP AVC','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"AVC được thành lập với định hướng lấy "},{"_type":"span","text":"chất lượng và an toàn làm ưu tiên hàng đầu","marks":["strong"]},{"_type":"span","text":" trong mọi giải pháp bếp công nghiệp. Chúng tôi không ngừng hoàn thiện sản phẩm, dịch vụ và quy trình thi công nhằm mang đến những hệ thống bếp hiệu quả, bền vững và tối ưu cho vận hành thực tế."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Với kinh nghiệm triển khai đa dạng các dự án F&B, nhà hàng – khách sạn, bếp trung tâm và khu công nghiệp trên toàn quốc, AVC cam kết mang đến "},{"_type":"span","text":"giải pháp phù hợp nhu cầu thực tế","marks":["strong"]},{"_type":"span","text":", hiệu quả và bền vững cho từng công trình."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Chúng tôi làm việc cùng chủ đầu tư, kiến trúc sư và nhà thầu để tạo ra những không gian bếp tối ưu công năng vận hành và đáp ứng nhu cầu đặc thù của từng đầu bếp. Đội ngũ kỹ sư, kỹ thuật viên giàu kinh nghiệm thực tế cùng "},{"_type":"span","text":"chuỗi giá trị khép kín","marks":["strong"]},{"_type":"span","text":" — tư vấn, thiết kế, sản xuất, thi công, hậu mãi — là nền tảng cho chất lượng của từng công trình."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"AVC tổ chức lắp đặt, bảo hành và bảo trì hệ thống bếp công nghiệp theo quy trình kỹ thuật rõ ràng, đảm bảo thiết bị vận hành "},{"_type":"span","text":"ổn định, an toàn và hiệu quả","marks":["strong"]},{"_type":"span","text":" trong suốt vòng đời dự án."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Chúng tôi tiếp tục hoàn thiện để dẫn đầu. Xây dựng tiêu chuẩn. "},{"_type":"span","text":"Kiến tạo tương lai của giải pháp bếp công nghiệp tại Việt Nam.","marks":["strong"]}]}]','tìm hiểu thêm','/gioi-thieu','LĨNH VỰC CHÚNG TÔI PHỤC VỤ','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"AVC cung cấp giải pháp bếp công nghiệp trọn gói cho các thị trường: Nhà hàng, Khách sạn, Bếp trung tâm, Căn tin khu công nghiệp, Bakery, Bar & Café."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Dịch vụ bao gồm: Tư vấn đầu tư, Thiết kế mặt bằng 2D/3D & MEP, Cung cấp thiết bị nhập khẩu và sản xuất, Thi công lắp đặt, Bảo hành và Bảo trì định kỳ."}]}]');
